/*
 * CREATED berganti nama menjadi AVAILABLE, dan baris lama ikut dipindahkan di
 * sini — sebelum constraint barunya dipasang.
 *
 * Keduanya berarti hal yang sama: kartu kosong yang siap ditempeli barang.
 * Namanya diganti ketika pelepasan kartu dibangun, sebab kartu yang kembali
 * dari truk masuk ke keadaan itu juga — dan "created" pada kartu yang sudah
 * empat puluh kali berputar membaca seolah ia baru dicetak. Blueprint SAP
 * memakai kata yang sama: "container dikembalikan ke status full/available".
 */
UPDATE "kanban"."TM_KANBAN" SET "CHR_STATUS" = 'AVAILABLE' WHERE "CHR_STATUS" = 'CREATED';
